<script setup lang="ts">
import {computed,reactive,ref,watch,nextTick} from 'vue'
import {Eye,Download} from 'lucide-vue-next'
import {Button} from '@/shared/ui/shadcn/button'
import BenefitsToolbar from './BenefitsToolbar.vue'
import BenefitsPagination from './BenefitsPagination.vue'
import * as XLSX from 'xlsx'
import {emptyVoucherFilters,filterVouchers,scopedMonths,voucherAssessment,voucherSignals,summarizeVouchers,voucherReport,type VoucherRecord,type VoucherGrouping} from '../voucher-analysis'
const props=defineProps<{records:VoucherRecord[];kind:'education'|'kindergarten';date:string}>()
const emit=defineEmits<{open:[id:string]}>()
const f=reactive(emptyVoucherFilters()),draft=reactive(emptyVoucherFilters()),view=ref('list'),page=ref(1),size=ref(20),group=ref<VoucherGrouping>('region'),exportType=ref('list'),filterError=ref(''),drillIds=ref<string[]|null>(null),drillName=ref('')
const statuses=['Kutilmoqda','Faollashtirilgan','Muddati yakunlangan'],base=computed(()=>filterVouchers(props.records,f,props.date,false)),filtered=computed(()=>filterVouchers(props.records,f,props.date)),rows=computed(()=>filtered.value.filter(r=>!drillIds.value||drillIds.value.includes(r.id))),shown=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value))
const cards=computed(()=>[{status:'',label:'Jami',tone:'total'},...statuses.map(status=>({status,label:status,tone:status==='Faollashtirilgan'?'good':status==='Kutilmoqda'?'warning':'danger'}))].map(c=>{const rr=c.status?base.value.filter(r=>r.status===c.status):base.value;return {...c,...summarizeVouchers(rr,props.date,f),share:base.value.length?Math.round(rr.length/base.value.length*1000)/10:0}}))
const signalLabels=[{key:'waiting',label:'Uzoq kutilmoqda',tone:'warning'},{key:'ending',label:'30 kunda tugaydi',tone:'warning'},{key:'missing',label:'Oylik ma’lumot yetishmaydi',tone:'warning'},{key:'low',label:'Foydalanish past',tone:'danger'}]
const signals=computed(()=>signalLabels.map(s=>({...s,count:filterVouchers(props.records,{...f,signal:''},props.date).filter(r=>voucherSignals(r,props.date,f)[s.key as 'waiting'|'ending'|'missing'|'low']).length})))
const regions=computed(()=>unique(props.records.flatMap(r=>r.placements.slice(-1).map(p=>p.region))))
const districts=computed(()=>unique(props.records.flatMap(r=>r.placements.slice(-1).filter(p=>!draft.region||p.region===draft.region).map(p=>p.district))))
const orgs=computed(()=>[...new Map(props.records.flatMap(r=>r.placements.slice(-1).filter(p=>(!draft.region||p.region===draft.region)&&(!draft.district||p.district===draft.district)).map(p=>[p.inn,p] as const))).values()])
const subjects=computed(()=>unique(props.records.flatMap(r=>r.placements.map(p=>p.subject)))),directions=computed(()=>unique(props.records.flatMap(r=>r.placements.map(p=>p.direction))))
const report=computed(()=>voucherReport(rows.value,group.value,props.date,f)),reportTotal=computed(()=>summarizeVouchers(rows.value,props.date,f))
const activeCount=computed(()=>Object.entries(f).filter(([k,v])=>!['query','status','dateField','waitingDays'].includes(k)&&!!v).length)
const filterSummary=computed(()=>{const labels:Record<string,string>={query:'Qidiruv',status:'Holat',region:'Hudud',district:'Tuman',organization:'Tashkilot INN',subject:'Fan',direction:'Yo‘nalish',slot:'Vaucher',from:'Sanadan',to:'Sanagacha',monthFrom:'Hisobot oyidan',monthTo:'Hisobot oyigacha',usage:'Foydalanish',payment:'To‘lov',changed:'O‘zgarganlar',signal:'Nazorat'};const values:Record<string,string>={low:'Past',medium:'O‘rtacha',good:'Yaxshi',unknown:'Baholanmagan',known:'Ma’lum',missing:'Ma’lumot yetishmaydi',zero:'Nol',waiting:'Uzoq kutilmoqda',ending:'30 kunda tugaydi'};return Object.entries(f).filter(([k,v])=>labels[k]&&!!v).map(([k,v])=>labels[k]+': '+(v===true?'Ha':values[String(v)]??v)).join(' · ')})
const invalidDates=computed(()=>!!(draft.from&&draft.to&&draft.from>draft.to||draft.monthFrom&&draft.monthTo&&draft.monthFrom>draft.monthTo))
watch(()=>draft.region,()=>{draft.district='';draft.organization=''});watch(()=>draft.district,()=>draft.organization='')
watch(()=>JSON.stringify(f),()=>{page.value=1;drillIds.value=null;drillName.value=''});watch(size,()=>page.value=1)
watch(view,value=>{if(exportType.value!=='pdf')exportType.value=value==='report'?'report':'list'})
const unique=(values:string[])=>[...new Set(values.filter(Boolean))].sort()
const cash=(n:number|null)=>n===null?'Ma’lumot yo‘q':n.toLocaleString('uz-UZ')+' so‘m'
const d=(s:string|null)=>s?s.split('-').reverse().join('.'):'—'
const assessment=(r:VoucherRecord)=>voucherAssessment(r,props.date,f)
const tone=(n:number|null)=>n===null?'warning':n<30?'danger':n<70?'warning':'good'
function reset(){filterError.value='';Object.assign(f,emptyVoucherFilters());Object.assign(draft,emptyVoucherFilters());drillIds.value=null;page.value=1}
function apply(){filterError.value='';if(invalidDates.value){filterError.value='Sana oralig‘ini tekshiring.';return}if(!Number.isInteger(draft.waitingDays)||draft.waitingDays<1||draft.waitingDays>365){filterError.value='Kutish chegarasi 1–365 kun bo‘lishi kerak.';return}const query=f.query,status=f.status,signal=f.signal;Object.assign(f,draft,{query,status,signal})}
function clearFilters(){const query=f.query,status=f.status;Object.assign(f,emptyVoucherFilters(),{query,status});Object.assign(draft,f)}
async function drill(name:string,ids:string[]){if(group.value==='month'&&/^\d{4}-\d{2}$/.test(name)){draft.monthFrom=name;draft.monthTo=name;f.monthFrom=name;f.monthTo=name;await nextTick()}drillIds.value=ids;drillName.value=name;view.value='list';page.value=1}
function metadata(){return [{Sahifa:props.kind==='education'?'To‘garak vaucherlari':'Bog‘cha vaucherlari','Holat sanasi':props.date,'Filterlar':JSON.stringify(f),'Guruhlash':group.value,'Kesim':'Joriy tashkilot / fan','Shakllantirilgan vaqt':new Date().toISOString()}]}
function reportData(){const total=reportTotal.value;return [{Guruh:'JAMI',Vaucherlar:total.vouchers,Bolalar:total.children,'Ma’lum to‘lovlar':total.amount,...(props.kind==='education'?{'Yo‘lkira':total.travel}:{}),'Ma’lumoti yetishmayotgan vaucherlar':total.missing},...report.value.map(r=>({Guruh:r.name,Vaucherlar:r.vouchers,Bolalar:r.children,'Ma’lum to‘lovlar':r.amount,...(props.kind==='education'?{'Yo‘lkira':r.travel}:{}),'Ma’lumoti yetishmayotgan vaucherlar':r.missing}))]}
function download(){if(exportType.value==='pdf'){view.value='report';requestAnimationFrame(()=>window.print());return}const book=XLSX.utils.book_new();if(exportType.value==='report'){XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(reportData()),'Hisobot')}else{XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows.value.map(r=>{const a=assessment(r),p=r.placements.slice(-1)[0];return {'Hujjat raqami':r.id,ID:r.number,Sana:r.created,FIO:r.name,JShShIR:r.pinfl,Yosh:r.age,Reja:r.planId,Holat:r.status,Tashkilot:p?.organization??'',INN:p?.inn??'',Hudud:p?.region??'',Tuman:p?.district??'',Fan:p?.subject??'',Yonalish:p?.direction??'',Faollashgan:r.start,Tugash:r.end,'Ma’lum to‘lov':a.amount,'Yo‘lkira':a.travel,'Yakunlangan oylar':a.expected,'Ma’lumot kelgan oylar':a.reported,'Foydalanish bahosi %':a.percent}})),'Royxat');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows.value.flatMap(r=>r.placements.map(p=>({Vaucher:r.id,Tashkilot:p.organization,INN:p.inn,Hudud:p.region,Tuman:p.district,Yonalish:p.direction,Fan:p.subject,'Kirish sanasi':p.entered,'Chiqish sanasi':p.left})))),'Otishlar');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows.value.flatMap(r=>scopedMonths(r,f).map(m=>({Vaucher:r.id,Oy:m.month,'Tolangan summa':m.amount,'Yolkira summasi':m.travel,Davomat:m.attendance??null,'Xabar sanasi':m.received??null})))),'Oylik monitoring')}
 XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(metadata()),'Parametrlar');XLSX.writeFile(book,(props.kind==='education'?'Togarak':'Bogcha')+'_'+(exportType.value==='report'?'hisobot':'royxat')+'.xlsx')}
</script>
<template>
<section class="benefits-registry voucher-workspace">
<BenefitsToolbar v-model="f.query" :label="kind==='education'?'Ta’lim vaucherlarini qidirish':'Bog‘cha vaucherlarini qidirish'" placeholder="Hujjat, ID, FIO, JShShIR yoki tashkilot" :active-count="activeCount" @clear="clearFilters" @apply="apply">
<template #filters><div class="voucher-filter-grid">
<label>Joriy tashkilot hududi<select v-model="draft.region"><option value="">Barcha hududlar</option><option v-for="r in regions" :key="r">{{ r }}</option></select></label>
<label>Tuman (shahar)<select v-model="draft.district"><option value="">Barchasi</option><option v-for="r in districts" :key="r">{{ r }}</option></select></label>
<label class="wide">Joriy tashkilot<select v-model="draft.organization"><option value="">Barcha tashkilotlar</option><option v-for="o in orgs" :key="o.inn" :value="o.inn">{{ o.organization }} ({{ o.inn }})</option></select></label>
<template v-if="kind==='education'"><label>Yo‘nalish<select v-model="draft.direction"><option value="">Barchasi</option><option v-for="v in directions" :key="v">{{ v }}</option></select></label><label>Fan<select v-model="draft.subject"><option value="">Barcha fanlar</option><option v-for="s in subjects" :key="s">{{ s }}</option></select></label><label>Fan vaucheri<select v-model="draft.slot"><option value="">Ikkalasi</option><option value="1">1-vaucher</option><option value="2">2-vaucher</option></select></label></template>
<label>Sana turi<select v-model="draft.dateField"><option value="created">Hujjat sanasi</option><option value="start">Faollashgan sana</option><option value="end">Tugash sanasi</option></select></label>
<label>Sanadan<input v-model="draft.from" type="date" /></label><label>Sanagacha<input v-model="draft.to" type="date" /></label>
<label>Hisobot oyi — dan<input v-model="draft.monthFrom" type="month" /></label><label>Hisobot oyi — gacha<input v-model="draft.monthTo" type="month" /></label>
<label>Foydalanish bahosi<select v-model="draft.usage"><option value="">Barchasi</option><option value="low">Past — 30% dan kam</option><option value="medium">O‘rtacha — 30–69%</option><option value="good">Yaxshi — 70% va yuqori</option><option value="unknown">Baholash uchun ma’lumot yetarli emas</option></select></label>
<label>To‘lov ma’lumoti<select v-model="draft.payment"><option value="">Barchasi</option><option value="missing">Yakunlangan oy ma’lumoti yetishmaydi</option><option value="known">Ma’lum summa bor</option><option value="zero">Ma’lum summa nol</option></select></label>
<label>Uzoq kutish chegarasi (kun)<input v-model.number="draft.waitingDays" type="number" min="1" max="365" /></label><label class="voucher-checkbox"><input v-model="draft.changed" type="checkbox" /> Tashkilot / fan o‘zgargan</label>
<p v-if="invalidDates" role="alert" class="wide danger">Boshlanish sanasi tugash sanasidan keyin bo‘lishi mumkin emas.</p>
</div></template>
<template #actions><div class="voucher-view-switch" aria-label="Sahifa ko‘rinishi"><Button :variant="view==='list'?'secondary':'ghost'" size="sm" @click="view='list'">Ro‘yxat</Button><Button :variant="view==='report'?'secondary':'ghost'" size="sm" @click="view='report'">Hisobot</Button></div><label class="sr-only" for="voucher-export">Yuklab olish turi</label><select id="voucher-export" v-model="exportType" class="voucher-export"><option value="list">Ro‘yxat · Excel</option><option value="report">Hisobot · Excel</option><option value="pdf">Hisobot · PDF / chop etish</option></select><Button variant="outline" size="sm" @click="download"><Download class="h-4 w-4" /> Yuklab olish</Button></template>
</BenefitsToolbar>
<p v-if="filterError" role="alert" class="danger">{{ filterError }}</p>
<section class="kg-status-cards" aria-label="Vaucherlar holati"><button v-for="c in cards" :key="c.status" :class="['kg-status-card inline-flex',c.tone,{selected:f.status===c.status}]" :aria-pressed="f.status===c.status" @click="f.status=f.status===c.status?'':c.status"><span class="kg-status-label"><i />{{ c.label }}</span><span class="kg-status-count"><strong>{{ c.vouchers }}</strong><span>{{ c.share }}%</span></span><span class="kg-status-metrics"><span><span>Noyob bolalar</span><b>{{ c.children }}</b></span><span><span>{{ kind==='education'?'To‘garak to‘lovi':'Ma’lum to‘lovlar' }}</span><b>{{ cash(c.amount) }}</b></span><span><span>Oy ma’lumoti yetishmaydi</span><b :class="{'kg-metric-warning':c.missing}">{{ c.missing }}</b></span></span></button></section>
<div class="voucher-signals" aria-label="Nazorat ko‘rsatkichlari"><button v-for="s in signals" :key="s.key" :class="[s.tone,{selected:f.signal===s.key}]" :aria-pressed="f.signal===s.key" @click="f.signal=f.signal===s.key?'':s.key">{{ s.key==='waiting'?f.waitingDays+'+ kun kutilmoqda':s.label }} <b>{{ s.count }}</b></button><span>{{ date }} holatiga</span></div>
<div v-if="activeCount||f.status||f.query||drillIds" class="voucher-filter-summary"><span :title="filterSummary">{{ rows.length }} vaucher · {{ new Set(rows.map(r=>r.personId)).size }} bola <template v-if="drillIds">· {{ drillName }}</template></span><Button variant="ghost" size="sm" @click="reset">Barcha filterlarni tozalash</Button></div>
<template v-if="view==='list'">
<div :class="['kg-list kg-table kg-register',{'ed-subject-register':kind==='education'}]"><table><thead><tr><th>Hujjat</th><th>Shaxs</th><th>{{ kind==='education'?'To‘garak':'Qabul' }}</th><th v-if="kind==='education'">Yo‘nalish (fan)</th><th>Holat</th><th>Foydalanish</th><th><span class="sr-only">Ko‘rish</span></th></tr></thead><tbody>
<tr v-for="r in shown" :key="r.id"><td><button class="kg-record-link" @click="emit('open',r.id)">{{ r.id }}</button> <span class="voucher-id">({{ r.number }})</span><small>{{ d(r.created) }}</small></td><td><b class="kg-cell-title kg-full-name">{{ r.name }}</b><small>{{ r.pinfl }} ({{ r.age }} yosh)</small></td>
<td><div v-for="(p,i) in r.placements" :key="i" class="voucher-placement"><div class="kg-organization-line"><b>{{ p.organization }}</b> <span>({{ p.inn||'—' }})</span></div><small>{{ p.region }} - {{ p.district }}</small><small :class="{'placement-current':i===r.placements.length-1}">Kirish: {{ d(p.entered) }} · {{ p.left?'Chiqish: '+d(p.left):r.status==='Muddati yakunlangan'?'Oxirgi tashkilot':'Joriy' }}</small></div><span v-if="!r.placements.length">—</span></td>
<td v-if="kind==='education'"><div v-for="(p,i) in r.placements" :key="i" class="voucher-placement"><b>{{ p.subject }}</b><small>{{ p.direction }}</small><small>Kirish: {{ d(p.entered) }}</small></div><small>{{ r.slot }}-fan vaucheri</small></td>
<td><span :class="['kg-badge',r.status==='Faollashtirilgan'?'good':r.status==='Kutilmoqda'?'warning':'neutral']">{{ r.status }}</span><small v-if="r.start">{{ d(r.start) }} — {{ d(r.end) }}</small></td>
<td><template v-if="r.start"><b :class="['kg-usage-amount',{'kg-list-missing':assessment(r).amount===null,'kg-error':assessment(r).amount===0}]">{{ cash(assessment(r).amount) }}</b><small>{{ assessment(r).amount===null?'—':assessment(r).used }} / {{ assessment(r).total }} oy · jami muddat</small><template v-if="assessment(r).percent!==null"><small :class="['kg-usage-percent',tone(assessment(r).percent)]">Baholash: {{ assessment(r).paid }} / {{ assessment(r).expected }} oy ({{ assessment(r).percent }}%)</small><div class="kg-usage-track" role="img" :aria-label="'Foydalanish '+assessment(r).percent+'%'"><span :class="tone(assessment(r).percent)" :style="{width:assessment(r).percent+'%'}" /></div></template><small v-else class="warning">{{ assessment(r).missing?assessment(r).missing+' oy ma’lumoti yo‘q':'Yakunlangan oy yo‘q' }}</small></template><span v-else>—</span></td>
<td><Button variant="ghost" size="icon" :aria-label="r.name+' kartasini ochish'" @click="emit('open',r.id)"><Eye class="h-4 w-4" /></Button></td></tr><tr v-if="!shown.length"><td :colspan="kind==='education'?7:6">Ma’lumot topilmadi.</td></tr></tbody></table></div>
<BenefitsPagination v-model:page="page" v-model:size="size" :total="rows.length" @reset="reset" />
</template>
<section v-else class="voucher-report" aria-label="Vaucherlar hisoboti"><div class="voucher-report-toolbar"><label>Guruhlash<select v-model="group"><option value="region">Hudud</option><option value="district">Tuman (shahar)</option><option value="organization">Tashkilot</option><option value="status">Holat</option><option v-if="kind==='education'" value="subject">Fan</option><option value="month">Hisobot oyi</option></select></label><span>{{ date }} · {{ kind==='education'?'To‘garak':'Bog‘cha' }} vaucherlari</span></div><p v-if="filterSummary" class="voucher-report-note">{{ filterSummary }}</p><p class="voucher-report-note">Summalar vaucher kesimida. Tashkilot va fan bo‘yicha guruhlash joriy biriktirishga asoslanadi; to‘lovning tashkilotlar o‘rtasidagi taqsimoti emas.</p><div class="kg-table"><table><thead><tr><th>Guruh</th><th>Vaucherlar</th><th>Noyob bolalar</th><th>{{ kind==='education'?'To‘garak to‘lovi':'Ma’lum to‘lovlar' }}</th><th v-if="kind==='education'">Yo‘lkira to‘lovi</th><th>Oy ma’lumoti yetishmaydi</th></tr></thead><tbody><tr class="voucher-report-total"><td>JAMI</td><td>{{ reportTotal.vouchers }}</td><td>{{ reportTotal.children }}</td><td>{{ cash(reportTotal.amount) }}</td><td v-if="kind==='education'">{{ cash(reportTotal.travel) }}</td><td>{{ reportTotal.missing }}</td></tr><tr v-for="r in report" :key="r.name"><td><button @click="drill(r.name,r.ids)">{{ r.name }}</button></td><td><button @click="drill(r.name,r.ids)">{{ r.vouchers }}</button></td><td><button @click="drill(r.name,r.ids)">{{ r.children }}</button></td><td>{{ cash(r.amount) }}</td><td v-if="kind==='education'">{{ cash(r.travel) }}</td><td>{{ r.missing }}</td></tr><tr v-if="!report.length"><td :colspan="kind==='education'?6:5">Ma’lumot topilmadi.</td></tr></tbody></table></div><p class="voucher-report-note">Bolalar guruhlar orasida takrorlanishi mumkin. JAMI noyob bolalar va vaucherlar bo‘yicha alohida hisoblangan.</p></section>
</section>
</template>
